// Server-side JWT verification (Node.js / jsonwebtoken)
const jwt = require('jsonwebtoken');

function verifyToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Access token missing' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) {
      // Token expired or signature invalid
      return res.status(403).json({ error: 'Token invalid or expired' });
    }
    req.user = decoded; // Attach decoded payload to request
    next();
  });
}

// Comparing two algorithms solving the same problem
// Find if two numbers in an array sum to a target

// Approach 1 — O(n²): nested loops
function hasPairSumNaive(arr, target) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] + arr[j] === target) return true;
    }
  }
  return false;
}

// Approach 2 — O(n): hash set lookup
function hasPairSumOptimal(arr, target) {
  const seen = new Set();
  for (const num of arr) {
    if (seen.has(target - num)) return true;
    seen.add(num);
  }
  return false;
}

