const socket = new WebSocket('wss://james.example.com/ws');

socket.addEventListener('open', () => {
  console.log('Connection established');
  socket.send(JSON.stringify({ type: 'subscribe', channel: 'live-feed' }));
});

socket.addEventListener('message', (event) => {
  const data = JSON.parse(event.data);
  updateDashboard(data); // real-time UI update
});

socket.addEventListener('close', (event) => {
  console.warn(`Connection closed: code=${event.code}, reason=${event.reason}`);
  // Reconnect logic with exponential backoff
  setTimeout(() => reconnect(), 3000);
});

socket.addEventListener('error', (error) => {
  console.error('WebSocket error:', error);
});

