.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  padding: 24px;
}

/* Item spanning 2 columns on large screens */
.card-featured {
  grid-column: span 2;
}

/* Named grid areas for a classic page layout */
.page-layout {
  display: grid;
  grid-template-areas:
    'header  header'
    'sidebar main'
    'footer  footer';
  grid-template-columns: 260px 1fr;
  grid-template-rows: auto 1fr auto;
